ee:message.ee:set-payload:
%dw 2.0
output application/json
var rawInteraction = (payload.payload default "{}") as String
var interaction = read(rawInteraction, "application/json")
var action = interaction.actions[0] default {}
var actionId = lower((action.action_id default "") as String)
var valueText = (action.value default "") as String
var value = if (valueText startsWith "{") read(valueText, "application/json") else {}
var approvalId = (value.approvalId default valueText default "selected approval") as String
var decision =
    if (actionId contains "approve") "approval"
    else if (actionId contains "reject") "rejection"
    else "change request"
---
{
    response_type: "ephemeral",
    replace_original: false,
    text:
        if (actionId contains "modify")
            "Logia noted the change request for `" ++ approvalId ++ "`. Open the Salesforce command center to adjust the recommendation safely."
        else
            "Logia received the " ++ decision ++ " for `" ++ approvalId ++ "`. Salesforce remains the system of record for the governed action."
}

%dw 2.0
output application/json
var text = trim((payload.text default "") as String)
var normalized = lower(text)
var parts = normalized splitBy " "
var profile = parts[1] default ""
var isDemo = normalized startsWith "demo"
var isDemoRun = normalized startsWith "demo run"
var isProfile = normalized startsWith "profile"
var isOrder = normalized startsWith "order"
var isReport = normalized startsWith "report"
var demoText =
    if (profile == "hospital")
        "Logia demo `hospital` uses `profile:hospital-private-large`: complaint, queue, room, stock, billing, partner delay, approval, Slack update, WhatsApp receipt, outcome."
    else if (profile == "airport")
        "Logia demo `airport` uses `profile:airport-operations`: passenger complaint, delay, gate, baggage, queue, equipment stock, protected passenger update, outcome."
    else if (profile == "hotel")
        "Logia demo `hotel` uses `profile:hotel-guest-operations`: guest complaint, room readiness, housekeeping, linen/food stock, billing, supplier follow-up, outcome."
    else if (profile == "bank" or profile == "banking")
        "Logia demo `bank` uses `profile:bank-service-operations`: client complaint, dispute, KYC delay, document evidence, compliance approval, callback, outcome."
    else
        "Use `/logia demo hospital|airport|hotel|bank` to preview a safe four-profile scenario."
var profileText =
    if (profile == "hospital")
        "Logia profile set to `profile:hospital-private-large` for this channel story. Future manager orders can use hospital wording."
    else if (profile == "airport")
        "Logia profile set to `profile:airport-operations` for this channel story. Future manager orders can use airport wording."
    else if (profile == "hotel")
        "Logia profile set to `profile:hotel-guest-operations` for this channel story. Future manager orders can use hotel wording."
    else if (profile == "bank" or profile == "banking")
        "Logia profile set to `profile:bank-service-operations` for this channel story. Future manager orders can use banking wording."
    else
        "Use `/logia profile hospital|airport|hotel|bank` to set the channel demo profile."
var orderText =
    if (isOrder and sizeOf(text) > 6)
        trim(text[6 to -1])
    else
        ""
var reportText =
    if (isReport and sizeOf(text) > 7)
        trim(text[7 to -1])
    else
        ""
var orderSummary =
    if (orderText == "")
        "No stock request details were provided. Try `/logia order gloves qty 500 due 3 days supplier supplier@example.com`."
    else
        "Manager stock request captured: " ++ orderText
var reportSummary =
    if (reportText == "")
        "No worker issue was provided. Try `/logia report gloves are low at pharmacy`."
    else
        "Worker report captured: " ++ reportText ++ ". Logia creates evidence and role tasks, then routes protected actions to the Operations Manager."
var demoRunText =
    if (normalized == "demo run hospital-surge")
        "Logia hospital-surge script: WhatsApp complaint -> evidence -> ten-agent plan -> manager approval -> Slack tasks -> protected supplier email or safe queue -> outcome metrics. Use this as the 5-7 minute judge demo."
    else
        "Use `/logia demo run hospital-surge` for the scripted showcase sequence."
var orderApprovalId = "approval-logia-supplier-order-001"
var orderRecommendationId = "recommendation-logia-supplier-order-001"
var orderButtonValue = write({
    approvalId: orderApprovalId,
    recommendationId: orderRecommendationId,
    tenantKey: "demo-mauritius"
}, "application/json")
var responseText =
    if (normalized startsWith "status")
        "Logia status request received. Check the Salesforce command center for facts, approval state, actions, and outcomes."
    else if (normalized == "queue")
        "Logia queue summary: Salesforce is the source of truth. Slack mirrors safe case, profile, module, status, owner, approval, action, evidence count, and outcome fields when Slack Lists are configured. Workers report issues; managers approve protected actions."
    else if (isProfile)
        profileText
    else if (isDemoRun)
        demoRunText
    else if (isDemo)
        demoText
    else if (isReport)
        reportSummary
    else if (isOrder)
        orderSummary ++ " Logia drafted a protected supplier email. Manager approval is required before any supplier email or order is sent."
    else
        "Try `/logia status <case-id|approval-id>`, `/logia queue`, `/logia profile hospital|airport|hotel|bank`, `/logia demo hospital|airport|hotel|bank`, `/logia demo run hospital-surge`, `/logia report <issue>`, or `/logia order <item> qty <amount> due <days> supplier <email>`. Logia keeps tasks and approvals in Salesforce, while Slack is for safe coordination."
var baseResponse = {
    response_type: if (isDemo or isDemoRun or isProfile or isReport or isOrder) "in_channel" else "ephemeral",
    text: responseText
}
---
if (isOrder)
    baseResponse ++ {
        blocks: [
            {
                "type": "section",
                "text": {
                    "type": "mrkdwn",
                    "text": "*Protected supplier order draft*\n" ++ orderSummary
                }
            },
            {
                "type": "section",
                "fields": [
                    {
                        "type": "mrkdwn",
                        "text": "*Profile*\nUniversal operations"
                    },
                    {
                        "type": "mrkdwn",
                        "text": "*Module*\nInventory and supply"
                    },
                    {
                        "type": "mrkdwn",
                        "text": "*Approval ID*\n`" ++ orderApprovalId ++ "`"
                    },
                    {
                        "type": "mrkdwn",
                        "text": "*Action*\n`SEND_VENDOR_EMAIL` mock queue"
                    }
                ]
            },
            {
                "type": "section",
                "text": {
                    "type": "mrkdwn",
                    "text": "*Draft email*\nSubject: Stock request approval needed\n\nHello supplier, please confirm availability, price, and earliest delivery for the requested stock. This message will stay blocked until the manager approves it."
                }
            },
            {
                "type": "actions",
                "elements": [
                    {
                        "type": "button",
                        "text": {
                            "type": "plain_text",
                            "text": "Approve"
                        },
                        "style": "primary",
                        "action_id": "approve_logia_supplier_order",
                        "value": orderButtonValue
                    },
                    {
                        "type": "button",
                        "text": {
                            "type": "plain_text",
                            "text": "Reject"
                        },
                        "style": "danger",
                        "action_id": "reject_logia_supplier_order",
                        "value": orderButtonValue
                    },
                    {
                        "type": "button",
                        "text": {
                            "type": "plain_text",
                            "text": "Modify"
                        },
                        "action_id": "modify_logia_supplier_order",
                        "value": orderButtonValue
                    }
                ]
            }
        ]
    }
else
    baseResponse

%dw 2.0
output application/json
---
{
    "messaging_product": "whatsapp",
    "to": vars.metaReplyTo,
    "type": "text",
    "text": {
        "body": "Thanks. Logia received this. A manager will review it."
    }
}

%dw 2.0
output application/xml
---
{
    Response: {
        Message: "Thanks. Logia received this. A manager will review it."
    }
}

%dw 2.0
output application/xml
---
{
    Response: {
        Message: "Thanks. Logia received this. A manager will review it."
    }
}
